class PatientRiskEvaluator:
    def __init__(self, tool_name):
        self.tool_name = tool_name

    def evaluate_risk(self, patient_name, age, temperature, heart_rate):
        if age < 0 or temperature < 0 or heart_rate < 0:
            raise ValueError("Age, temperature, and heart rate must not be negative.")

        if temperature >= 39.0 or heart_rate >= 120:
            return f"High Risk: Immediate medical review suggested for {patient_name}."
        elif 37.5 <= temperature <= 38.9 or 100 <= heart_rate <= 119:
            return f"Moderate Risk: Monitor {patient_name} closely."
        else:
            return f"Low Risk: {patient_name} is currently stable."


# Example usage
if __name__ == "__main__":
    evaluator = PatientRiskEvaluator("HealthCheck AI")
    result = evaluator.evaluate_risk("John Doe", 45, 38.2, 105)
    print(f"Tool: {evaluator.tool_name}")
    print(result)
